def transform(grid):
    h, w = len(grid), len(grid[0])
    diagonal_colors = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                d = c - r
                diagonal_colors.setdefault(d, set()).add(color)

    # Find the shortest diagonal repeat period consistent with all clues.
    period = None
    for p in range(1, 2 * max(h, w) + 1):
        residues = {}
        valid = True
        for d, colors in diagonal_colors.items():
            if len(colors) != 1:
                valid = False
                break
            color = next(iter(colors))
            residue = d % p
            if residue in residues and residues[residue] != color:
                valid = False
                break
            residues[residue] = color
        if valid:
            period = p
            break

    if period is None:
        return [row[:] for row in grid]

    residues = {}
    for d, colors in diagonal_colors.items():
        if len(colors) == 1:
            residues[d % period] = next(iter(colors))

    return [
        [residues.get((c - r) % period, grid[r][c]) for c in range(w)]
        for r in range(h)
    ]
